import java.text.NumberFormat;
import java.util.Scanner;
public class JIfElseWages2
{
	public static void main (String[] args)
	{
		// Khutwa 1: 'Arif al-mutaghayyirat allati nahtajuha li hadha al-barnamaj
		final double RATE = 8.25; 
		final int STANDARD = 40; 
		final int WEEKEND_PAY_MIN = 30; 
		final int WEEKEND_PAY_MAX = 50; 
		double wage = 0.0;
		// Khutwa 2: Iqra' al-bayanat al-mudkhalah
		Scanner scan = new Scanner (System.in);
		System.out.println("Adkhil 'adad al-saa'at allati 'amilaha al-muwazzaf: ");
		int hours = scan.nextInt();
		System.out.println("Adkhil 'adad al-ayyaam allati 'amila fiha al-muwazzaf khilal ayyam al-usbu': ");
		int noWeekendDays = scan.nextInt();
		scan.close();
		// Khutwa 3: Idfa' ajr al-saa'at al-ziyadah bi marra wa nisf min nisbati al-ajr al-'adi
		if (hours > STANDARD) {
			wage = STANDARD * RATE + (hours-STANDARD) * (RATE * 1.5);
		} else {
			wage = hours * RATE;
		}
		// Khutwa 4: Akhudh fi al-i'tibar al-ajr al-izafi 'ala al-'amal fi ayyam al-usbu'
		if (noWeekendDays < 5) {
			wage += (noWeekendDays * WEEKEND_PAY_MIN);
		} else {
			wage += (noWeekendDays * WEEKEND_PAY_MAX);
		}
		// Khutwa 5: Taba' al-ajr al-mahsub
		NumberFormat fmt = NumberFormat.getCurrencyInstance();
		System.out.println("Al-ajr: " + fmt.format(wage));
	}
}
